-- Part 2 of 4. Run the parts in order.
-- =====================================================================
-- Akeso reference data seed
-- 30 diseases, 74 symptoms, 49 medicines,
-- 97 drug-drug interaction pairs, 12 multi-drug rules.
--
-- Researched from StatPearls (NCBI Bookshelf), WHO, CDC, DOH Philippines,
-- PSMID/PCP, GINA, GOLD, ADA, AHA/ESC, NICE and FDA labels on DailyMed.
-- Every clinical reference URL was opened and checked when this file was
-- made. Textbook ("mother book") references carry no URL on purpose.
--
-- Educational reference content for a student platform, not a substitute
-- for current product labeling or clinical judgment.
--
-- Safe to run more than once: rows with these ids are updated, and their
-- child rows (lists, links, references) are replaced.
-- Requires database/migrations/001_medication_safety_reference.sql.
-- =====================================================================


BEGIN;

-- =================================================================== MEDICINES

CREATE TEMP TABLE _seed_medicines ON COMMIT DROP AS SELECT id, name, generic_name, trade_name, drug_class, category, description, dosage_info, dosage_text, storage_instructions, storage, black_box_warning, international_generic_name, source_attribution, is_published FROM public.medicines WITH NO DATA;
UPDATE public.medicines AS x SET name = t.name, generic_name = t.generic_name, trade_name = t.trade_name, drug_class = t.drug_class, category = t.category, description = t.description, dosage_info = t.dosage_info, dosage_text = t.dosage_text, storage_instructions = t.storage_instructions, storage = t.storage, black_box_warning = t.black_box_warning, international_generic_name = t.international_generic_name, source_attribution = t.source_attribution, is_published = t.is_published, updated_at = now()
  FROM _seed_medicines AS t WHERE x.id = t.id;
  SELECT id, name, generic_name, trade_name, drug_class, category, description, dosage_info, dosage_text, storage_instructions, storage, black_box_warning, international_generic_name, source_attribution, is_published FROM _seed_medicines AS t
  WHERE NOT EXISTS (SELECT 1 FROM public.medicines AS x WHERE x.id = t.id);




COMMIT;
