INSERT INTO _seed_medicines (id, name, generic_name, trade_name, drug_class, category, description, dosage_info, dosage_text, storage_instructions, storage, black_box_warning, international_generic_name, source_attribution, is_published) VALUES
    ('med_paracetamol', 'Paracetamol', 'Paracetamol (acetaminophen)', 'Biogesic', 'Analgesic / antipyretic (para-aminophenol)', 'OTC', 'Paracetamol is thought to act mainly centrally, reducing prostaglandin synthesis via inhibition of cyclooxygenase pathways in the CNS, with a possible contribution from its metabolite AM404 acting on cannabinoid and TRPV1 systems. It has analgesic and antipyretic effects but minimal peripheral anti-inflammatory activity, and is a first-line agent for mild-to-moderate pain and fever.', 'Adults: 500-1000 mg orally every 4-6 hours as needed (minimum interval 4 hours). Maximum 4,000 mg in 24 hours from all sources; OTC labels for 500 mg tablets direct 2 tablets every 6 hours, not exceeding 6 tablets (3,000 mg) in 24 hours unless directed by a physician. Lower daily doses/longer intervals are used in severe renal impairment and hepatic impairment. Refer to current product labeling.', 'Adults: 500-1000 mg orally every 4-6 hours as needed (minimum interval 4 hours). Maximum 4,000 mg in 24 hours from all sources; OTC labels for 500 mg tablets direct 2 tablets every 6 hours, not exceeding 6 tablets (3,000 mg) in 24 hours unless directed by a physician. Lower daily doses/longer intervals are used in severe renal impairment and hepatic impairment. Refer to current product labeling.', 'Store at 20-25 C (68-77 F).', 'Store at 20-25 C (68-77 F).', 'OTC oral labels carry a liver warning (severe liver damage with >4,000 mg/24 h, with other acetaminophen-containing products, or with 3 or more alcoholic drinks daily) rather than a boxed warning. Prescription and IV acetaminophen products carry a boxed warning for hepatotoxicity (acute liver failure, sometimes requiring transplant or fatal) and dosing errors.', 'paracetamol', 'StatPearls: Acetaminophen; FDA OTC Drug Facts label (Tylenol Extra Strength) via DailyMed; Goodman & Gilman''s 14th ed.', true),
    ('med_ibuprofen', 'Ibuprofen', 'Ibuprofen', 'Medicol Advance', 'NSAID (propionic acid derivative)', 'OTC', 'Ibuprofen is a non-selective, reversible inhibitor of COX-1 and COX-2 that reduces prostaglandin synthesis, producing analgesic, antipyretic and anti-inflammatory effects. It is widely used for mild-to-moderate pain, fever, dysmenorrhea and inflammatory joint conditions.', 'Adults (OTC): 200-400 mg orally every 4-6 hours as needed, max 1,200 mg/day. Prescription: mild-to-moderate pain 400 mg every 4-6 hours as needed; rheumatoid arthritis/osteoarthritis 1,200-3,200 mg/day in divided doses. Take with food or milk; use the lowest effective dose for the shortest duration. Refer to current product labeling.', 'Adults (OTC): 200-400 mg orally every 4-6 hours as needed, max 1,200 mg/day. Prescription: mild-to-moderate pain 400 mg every 4-6 hours as needed; rheumatoid arthritis/osteoarthritis 1,200-3,200 mg/day in divided doses. Take with food or milk; use the lowest effective dose for the shortest duration. Refer to current product labeling.', 'Store at room temperature; avoid excessive heat above 40 C (104 F).', 'Store at room temperature; avoid excessive heat above 40 C (104 F).', 'Cardiovascular risk: NSAIDs increase the risk of serious cardiovascular thrombotic events, myocardial infarction and stroke, which can be fatal; contraindicated for peri-operative pain in CABG surgery. Gastrointestinal risk: increased risk of serious GI bleeding, ulceration and perforation, which can be fatal and may occur without warning; older adults are at greater risk.', 'ibuprofen', 'StatPearls: Ibuprofen; FDA prescription ibuprofen tablet label via DailyMed; Goodman & Gilman''s 14th ed.', true),
    ('med_mefenamic_acid', 'Mefenamic Acid', 'Mefenamic acid', 'Dolfenal', 'NSAID (fenamate)', 'OTC', 'Mefenamic acid is an anthranilic acid (fenamate) NSAID that inhibits cyclooxygenase and prostaglandin synthesis. It is used for short-term relief of mild-to-moderate pain and for primary dysmenorrhea.', 'Adults and adolescents >= 14 years: 500 mg orally as an initial dose, then 250 mg every 6 hours as needed, usually not exceeding 1 week for acute pain. Primary dysmenorrhea: 500 mg initially, then 250 mg every 6 hours, starting with onset of bleeding and usually not needed beyond 2-3 days. Take with food. Refer to current product labeling.', 'Adults and adolescents >= 14 years: 500 mg orally as an initial dose, then 250 mg every 6 hours as needed, usually not exceeding 1 week for acute pain. Primary dysmenorrhea: 500 mg initially, then 250 mg every 6 hours, starting with onset of bleeding and usually not needed beyond 2-3 days. Take with food. Refer to current product labeling.', 'Store at 25 C (77 F); excursions permitted to 15-30 C (59-86 F).', 'Store at 25 C (77 F); excursions permitted to 15-30 C (59-86 F).', 'Cardiovascular risk: increased risk of serious cardiovascular thrombotic events, myocardial infarction and stroke, which can be fatal; contraindicated in the setting of CABG surgery. Gastrointestinal risk: increased risk of serious GI bleeding, ulceration and perforation, which can be fatal.', 'mefenamic acid', 'FDA mefenamic acid capsule label via DailyMed; StatPearls: NSAIDs; Goodman & Gilman''s 14th ed.', true),
    ('med_aspirin', 'Aspirin (low-dose)', 'Aspirin (acetylsalicylic acid), low dose', 'Aspilets', 'Antiplatelet (salicylate)', 'OTC', 'Aspirin irreversibly acetylates platelet cyclooxygenase-1, blocking thromboxane A2 synthesis for the life of the platelet and thereby inhibiting platelet aggregation. At low doses it is used for acute coronary syndromes and secondary prevention of cardiovascular and cerebrovascular events.', 'Adults, cardiovascular prevention: 75-100 mg orally once daily (80-81 mg tablets are common). Acute coronary syndrome: loading dose 162-325 mg (chewed), then 75-100 mg once daily. Refer to current product labeling.', 'Adults, cardiovascular prevention: 75-100 mg orally once daily (80-81 mg tablets are common). Acute coronary syndrome: loading dose 162-325 mg (chewed), then 75-100 mg once daily. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) in a dry place.', 'Store at 20-25 C (68-77 F) in a dry place.', NULL, 'acetylsalicylic acid', 'StatPearls: Salicylic Acid (Aspirin); FDA OTC Drug Facts label (aspirin 81 mg) via DailyMed; Goodman & Gilman''s 14th ed.', true),
    ('med_clopidogrel', 'Clopidogrel', 'Clopidogrel (as bisulfate)', 'Plavix', 'Antiplatelet (P2Y12 inhibitor)', 'Prescription', 'Clopidogrel is a prodrug activated mainly by CYP2C19 to a metabolite that irreversibly blocks the platelet P2Y12 ADP receptor, preventing downstream glycoprotein IIb/IIIa activation and platelet aggregation. It is used, often with aspirin, in acute coronary syndromes and for secondary prevention after MI, stroke or peripheral arterial disease.', 'Adults: acute coronary syndrome (NSTE-ACS) 300 mg loading dose, then 75 mg once daily with aspirin; STEMI 75 mg once daily with or without a loading dose. Recent MI, recent stroke or established peripheral arterial disease: 75 mg once daily, with or without food. Discontinue 5 days before elective surgery when feasible. Refer to current product labeling.', 'Adults: acute coronary syndrome (NSTE-ACS) 300 mg loading dose, then 75 mg once daily with aspirin; STEMI 75 mg once daily with or without a loading dose. Recent MI, recent stroke or established peripheral arterial disease: 75 mg once daily, with or without food. Discontinue 5 days before elective surgery when feasible. Refer to current product labeling.', 'Store at 25 C (77 F); excursions permitted to 15-30 C (59-86 F).', 'Store at 25 C (77 F); excursions permitted to 15-30 C (59-86 F).', 'Diminished antiplatelet effect in patients with two loss-of-function CYP2C19 alleles (poor metabolizers), who have higher cardiovascular event rates at recommended doses; genetic testing is available, and an alternative P2Y12 inhibitor should be considered in identified poor metabolizers.', 'clopidogrel', 'FDA Plavix label via DailyMed; StatPearls: Clopidogrel; Goodman & Gilman''s 14th ed.', true),
    ('med_warfarin', 'Warfarin', 'Warfarin sodium', 'Coumadin', 'Anticoagulant (vitamin K antagonist)', 'Prescription', 'Warfarin inhibits vitamin K epoxide reductase (VKORC1), depleting reduced vitamin K and decreasing hepatic synthesis of functional clotting factors II, VII, IX and X (and proteins C and S). It is used for prevention and treatment of venous thromboembolism and thromboembolism in atrial fibrillation and mechanical heart valves, with dosing guided by the INR.', 'Adults: usual initial dose 2-5 mg orally once daily, then individualized to the INR (target 2.0-3.0 for most indications, including VTE and atrial fibrillation; higher targets for some mechanical valves). Dose requirements vary with age, CYP2C9/VKORC1 genotype, diet and interacting drugs. Refer to current product labeling.', 'Adults: usual initial dose 2-5 mg orally once daily, then individualized to the INR (target 2.0-3.0 for most indications, including VTE and atrial fibrillation; higher targets for some mechanical valves). Dose requirements vary with age, CYP2C9/VKORC1 genotype, diet and interacting drugs. Refer to current product labeling.', 'Store at controlled room temperature per the manufacturer''s labeling.', 'Store at controlled room temperature per the manufacturer''s labeling.', 'Bleeding risk: warfarin can cause major or fatal bleeding. Regular INR monitoring is required for all patients; drugs, dietary changes and other factors affect INR levels; patients should be instructed about bleeding prevention and to report signs and symptoms of bleeding.', 'warfarin', 'FDA warfarin sodium label via DailyMed; StatPearls: Warfarin; Goodman & Gilman''s 14th ed.', true),
    ('med_amoxicillin', 'Amoxicillin', 'Amoxicillin (as trihydrate)', 'Himox', 'Antibiotic (aminopenicillin)', 'Prescription', 'Amoxicillin is a bactericidal beta-lactam that binds penicillin-binding proteins and inhibits transpeptidation in bacterial cell-wall synthesis, leading to cell lysis. It is a first-line agent for many respiratory, ENT, skin and urinary infections and a component of H. pylori eradication regimens.', 'Adults: mild-to-moderate ENT, skin or genitourinary infection 500 mg every 12 hours or 250 mg every 8 hours; severe infections and lower respiratory tract infection 875 mg every 12 hours or 500 mg every 8 hours. H. pylori: 1 g twice daily with clarithromycin and a PPI (triple therapy) for 14 days. GFR 10-30 mL/min: 250-500 mg every 12 hours; GFR < 10: 250-500 mg every 24 hours; do not use the 875 mg dose if GFR < 30. Refer to current product labeling.', 'Adults: mild-to-moderate ENT, skin or genitourinary infection 500 mg every 12 hours or 250 mg every 8 hours; severe infections and lower respiratory tract infection 875 mg every 12 hours or 500 mg every 8 hours. H. pylori: 1 g twice daily with clarithromycin and a PPI (triple therapy) for 14 days. GFR 10-30 mL/min: 250-500 mg every 12 hours; GFR < 10: 250-500 mg every 24 hours; do not use the 875 mg dose if GFR < 30. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); excursions permitted to 15-30 C (59-86 F).', 'Store at 20-25 C (68-77 F); excursions permitted to 15-30 C (59-86 F).', NULL, 'amoxicillin', 'FDA amoxicillin capsule label via DailyMed; StatPearls: Amoxicillin; Goodman & Gilman''s 14th ed.', true),
    ('med_coamoxiclav', 'Co-amoxiclav (Amoxicillin + Clavulanic acid)', 'Amoxicillin + clavulanate potassium', 'Augmentin', 'Antibiotic (aminopenicillin + beta-lactamase inhibitor)', 'Prescription', 'Amoxicillin inhibits bacterial cell-wall synthesis by binding penicillin-binding proteins, while clavulanic acid inhibits many beta-lactamases, protecting amoxicillin from degradation and extending coverage to beta-lactamase-producing organisms (e.g., H. influenzae, M. catarrhalis, many anaerobes and some Enterobacterales). It is used for sinusitis, otitis media, lower respiratory, skin, bite-wound and urinary infections.', 'Adults: 500 mg every 12 hours or 250 mg every 8 hours (as amoxicillin component); severe infections and respiratory tract infections 875 mg every 12 hours or 500 mg every 8 hours. CrCl < 30 mL/min: do not use 875 mg tablets; CrCl 10-30: 250-500 mg every 12 hours; CrCl < 10: 250-500 mg every 24 hours. Take at the start of a meal. Refer to current product labeling.', 'Adults: 500 mg every 12 hours or 250 mg every 8 hours (as amoxicillin component); severe infections and respiratory tract infections 875 mg every 12 hours or 500 mg every 8 hours. CrCl < 30 mL/min: do not use 875 mg tablets; CrCl 10-30: 250-500 mg every 12 hours; CrCl < 10: 250-500 mg every 24 hours. Take at the start of a meal. Refer to current product labeling.', 'Store tablets at or below 25 C (77 F); dispense in original container.', 'Store tablets at or below 25 C (77 F); dispense in original container.', NULL, 'amoxicillin + clavulanic acid', 'FDA Augmentin label via DailyMed; StatPearls: Amoxicillin Clavulanate; Goodman & Gilman''s 14th ed.', true),
    ('med_azithromycin', 'Azithromycin', 'Azithromycin', 'Zithromax', 'Antibiotic (macrolide)', 'Prescription', 'Azithromycin is an azalide macrolide that binds the 23S rRNA of the 50S ribosomal subunit and inhibits bacterial protein synthesis; it is mainly bacteriostatic. Its long tissue half-life allows short once-daily courses for respiratory infections, atypical pneumonia and sexually transmitted infections.', 'Adults: community-acquired pneumonia (mild, oral), pharyngitis, skin infections: 500 mg once on day 1, then 250 mg once daily on days 2-5; acute bacterial sinusitis/AECOPD: 500 mg once daily for 3 days. Non-gonococcal urethritis/cervicitis (C. trachomatis): 1 g single dose. Refer to current product labeling.', 'Adults: community-acquired pneumonia (mild, oral), pharyngitis, skin infections: 500 mg once on day 1, then 250 mg once daily on days 2-5; acute bacterial sinusitis/AECOPD: 500 mg once daily for 3 days. Non-gonococcal urethritis/cervicitis (C. trachomatis): 1 g single dose. Refer to current product labeling.', 'Store tablets at 20-25 C (68-77 F).', 'Store tablets at 20-25 C (68-77 F).', NULL, 'azithromycin', 'FDA Zithromax label via DailyMed; StatPearls: Azithromycin; Goodman & Gilman''s 14th ed.', true),
    ('med_clarithromycin', 'Clarithromycin', 'Clarithromycin', 'Klaricid', 'Antibiotic (macrolide)', 'Prescription', 'Clarithromycin binds the 50S ribosomal subunit and inhibits bacterial protein synthesis. It covers respiratory and atypical pathogens and is a key component of H. pylori triple therapy, but it is a strong CYP3A4 inhibitor with many clinically important drug interactions.', 'Adults: pharyngitis/tonsillitis 250 mg every 12 hours for 10 days; community-acquired pneumonia and other respiratory infections 250-500 mg every 12 hours for 7-14 days. H. pylori: 500 mg every 12 hours with amoxicillin and a PPI for 10-14 days. CrCl < 30 mL/min: reduce dose by 50%. Refer to current product labeling.', 'Adults: pharyngitis/tonsillitis 250 mg every 12 hours for 10 days; community-acquired pneumonia and other respiratory infections 250-500 mg every 12 hours for 7-14 days. H. pylori: 500 mg every 12 hours with amoxicillin and a PPI for 10-14 days. CrCl < 30 mL/min: reduce dose by 50%. Refer to current product labeling.', 'Store at controlled room temperature per the manufacturer''s labeling.', 'Store at controlled room temperature per the manufacturer''s labeling.', NULL, 'clarithromycin', 'FDA clarithromycin tablet label via DailyMed; StatPearls: Macrolides; Goodman & Gilman''s 14th ed.', true),
    ('med_ceftriaxone', 'Ceftriaxone', 'Ceftriaxone (as sodium)', 'Rocephin', 'Antibiotic (third-generation cephalosporin)', 'Prescription', 'Ceftriaxone is a parenteral third-generation cephalosporin that binds penicillin-binding proteins and disrupts peptidoglycan cross-linking, producing bactericidal activity. Its long half-life permits once-daily dosing, and it is widely used for pneumonia, meningitis, pyelonephritis, typhoid fever, gonorrhea and sepsis.', 'Adults: usual 1-2 g IV or IM once daily (or in equally divided doses twice daily); total daily dose should not exceed 4 g. Higher dosing is used for meningitis. Surgical prophylaxis: single 1 g IV dose 30 minutes to 2 hours before surgery. No adjustment for renal or hepatic impairment alone; with both, do not exceed 2 g/day. Refer to current product labeling.', 'Adults: usual 1-2 g IV or IM once daily (or in equally divided doses twice daily); total daily dose should not exceed 4 g. Higher dosing is used for meningitis. Surgical prophylaxis: single 1 g IV dose 30 minutes to 2 hours before surgery. No adjustment for renal or hepatic impairment alone; with both, do not exceed 2 g/day. Refer to current product labeling.', 'Store powder at 20-25 C (68-77 F); protect from light.', 'Store powder at 20-25 C (68-77 F); protect from light.', NULL, 'ceftriaxone', 'FDA ceftriaxone for injection label via DailyMed; StatPearls: Third-Generation Cephalosporins; Goodman & Gilman''s 14th ed.', true),
    ('med_ciprofloxacin', 'Ciprofloxacin', 'Ciprofloxacin (as hydrochloride)', 'Ciprobay', 'Antibiotic (fluoroquinolone)', 'Prescription', 'Ciprofloxacin is a bactericidal fluoroquinolone that inhibits bacterial DNA gyrase and topoisomerase IV, blocking DNA replication. It is especially active against Gram-negative organisms including Pseudomonas aeruginosa, but because of serious class toxicities it is reserved for infections where benefits outweigh risks.', 'Adults (oral): acute uncomplicated cystitis 250 mg every 12 hours for 3 days; other UTI 250-500 mg every 12 hours for 7-14 days; other infections 500-750 mg every 12 hours. IV: 400 mg every 8-12 hours. CrCl 30-50 mL/min: 250-500 mg every 12 hours; CrCl 5-29: 250-500 mg every 18 hours. Separate from multivalent cations (take 2 hours before or 6 hours after). Refer to current product labeling.', 'Adults (oral): acute uncomplicated cystitis 250 mg every 12 hours for 3 days; other UTI 250-500 mg every 12 hours for 7-14 days; other infections 500-750 mg every 12 hours. IV: 400 mg every 8-12 hours. CrCl 30-50 mL/min: 250-500 mg every 12 hours; CrCl 5-29: 250-500 mg every 18 hours. Separate from multivalent cations (take 2 hours before or 6 hours after). Refer to current product labeling.', 'Store at controlled room temperature per the manufacturer''s labeling.', 'Store at controlled room temperature per the manufacturer''s labeling.', 'Fluoroquinolones, including ciprofloxacin, are associated with disabling and potentially irreversible serious adverse reactions that may occur together: tendinitis and tendon rupture, peripheral neuropathy and CNS effects; discontinue immediately if these occur. May exacerbate muscle weakness in myasthenia gravis; avoid in patients with known history of myasthenia gravis. Reserve for patients with no alternative treatment options for acute bacterial exacerbation of chronic bronchitis, acute uncomplicated cystitis and acute bacterial sinusitis.', 'ciprofloxacin', 'FDA CIPRO label via DailyMed; StatPearls: Ciprofloxacin; Goodman & Gilman''s 14th ed.', true),
    ('med_nitrofurantoin', 'Nitrofurantoin', 'Nitrofurantoin (monohydrate/macrocrystals)', 'Macrodantin', 'Antibiotic (nitrofuran)', 'Prescription', 'Nitrofurantoin is reduced by bacterial flavoproteins to reactive intermediates that damage ribosomal proteins, DNA and other macromolecules, giving it multiple targets and low resistance rates. It concentrates in urine with low serum levels and is used for uncomplicated lower urinary tract infection (cystitis), not pyelonephritis.', 'Adults: monohydrate/macrocrystals (e.g., Macrobid) 100 mg every 12 hours for 7 days (5-7 days commonly used for acute cystitis); macrocrystals 50-100 mg four times daily. Long-term prophylaxis: 50-100 mg at bedtime. Take with food. Refer to current product labeling.', 'Adults: monohydrate/macrocrystals (e.g., Macrobid) 100 mg every 12 hours for 7 days (5-7 days commonly used for acute cystitis); macrocrystals 50-100 mg four times daily. Long-term prophylaxis: 50-100 mg at bedtime. Take with food. Refer to current product labeling.', 'Store at controlled room temperature 15-30 C (59-86 F).', 'Store at controlled room temperature 15-30 C (59-86 F).', NULL, 'nitrofurantoin', 'FDA Macrobid label via DailyMed; StatPearls: Nitrofurantoin; Goodman & Gilman''s 14th ed.', true),
    ('med_doxycycline', 'Doxycycline', 'Doxycycline (as hyclate)', 'Vibramycin', 'Antibiotic (tetracycline)', 'Prescription', 'Doxycycline binds the 30S ribosomal subunit and blocks aminoacyl-tRNA binding, inhibiting bacterial protein synthesis (bacteriostatic). It is used for rickettsial infections, leptospirosis, atypical pneumonia, chlamydia, Lyme disease, acne and malaria prophylaxis.', 'Adults: 200 mg on day 1 (100 mg every 12 hours), then 100 mg/day; for more severe infections, 100 mg every 12 hours throughout. Take with a full glass of water, upright, and not immediately before bed. No renal dose adjustment. Refer to current product labeling.', 'Adults: 200 mg on day 1 (100 mg every 12 hours), then 100 mg/day; for more severe infections, 100 mg every 12 hours throughout. Take with a full glass of water, upright, and not immediately before bed. No renal dose adjustment. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) in a tight, light-resistant container.', 'Store at 20-25 C (68-77 F) in a tight, light-resistant container.', NULL, 'doxycycline', 'FDA doxycycline hyclate label via DailyMed; StatPearls: Doxycycline Hyclate; Goodman & Gilman''s 14th ed.', true),
    ('med_rifampicin', 'Rifampicin', 'Rifampicin (rifampin)', 'Rimactane', 'Antituberculosis agent (rifamycin)', 'Prescription', 'Rifampicin inhibits bacterial DNA-dependent RNA polymerase, blocking transcription, and is bactericidal against Mycobacterium tuberculosis. It is a cornerstone of first-line TB therapy (with isoniazid, pyrazinamide and ethambutol) and is a potent inducer of CYP3A4 and other drug-metabolizing enzymes, causing many drug interactions.', 'Adults (tuberculosis): 10 mg/kg once daily, not to exceed 600 mg/day, orally or IV, always in combination with other antituberculosis drugs. Take 1 hour before or 2 hours after a meal with a full glass of water. Meningococcal carriers: 600 mg every 12 hours for 2 days. Refer to current product labeling.', 'Adults (tuberculosis): 10 mg/kg once daily, not to exceed 600 mg/day, orally or IV, always in combination with other antituberculosis drugs. Take 1 hour before or 2 hours after a meal with a full glass of water. Meningococcal carriers: 600 mg every 12 hours for 2 days. Refer to current product labeling.', 'Store at 25 C (77 F); protect from light and from temperatures above 40 C (104 F).', 'Store at 25 C (77 F); protect from light and from temperatures above 40 C (104 F).', NULL, 'rifampicin', 'FDA Rifadin label via DailyMed; StatPearls: Rifampin; Goodman & Gilman''s 14th ed.', true),
    ('med_isoniazid', 'Isoniazid', 'Isoniazid', 'Pharex Isoniazid', 'Antituberculosis agent', 'Prescription', 'Isoniazid is a prodrug activated by mycobacterial catalase-peroxidase (KatG) that inhibits mycolic acid synthesis in the cell wall, making it bactericidal against actively dividing M. tuberculosis. It is used in first-line combination therapy for active TB and as monotherapy or in combination for latent TB infection.', 'Adults: 5 mg/kg (up to 300 mg) orally once daily, or 15 mg/kg (up to 900 mg) two or three times weekly, in combination with other antituberculosis agents for active TB. Latent TB: 300 mg daily for 6-9 months (or combination regimens). Pyridoxine (vitamin B6) 25-50 mg daily is recommended for patients at risk of neuropathy. Refer to current product labeling.', 'Adults: 5 mg/kg (up to 300 mg) orally once daily, or 15 mg/kg (up to 900 mg) two or three times weekly, in combination with other antituberculosis agents for active TB. Latent TB: 300 mg daily for 6-9 months (or combination regimens). Pyridoxine (vitamin B6) 25-50 mg daily is recommended for patients at risk of neuropathy. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); protect from moisture and light.', 'Store at 20-25 C (68-77 F); protect from moisture and light.', 'Severe and sometimes fatal hepatitis may occur and may develop even after many months of treatment. Risk is age-related and increases with daily alcohol use, chronic liver disease and injection drug use; women (particularly Black and Hispanic women) and the postpartum period may also carry higher risk. Patients should be monitored and interviewed monthly for symptoms, with liver enzyme testing in higher-risk patients; therapy should be stopped if hepatitis is suspected.', 'isoniazid', 'FDA isoniazid tablet label via DailyMed; StatPearls: Isoniazid; Goodman & Gilman''s 14th ed.', true),
    ('med_pyrazinamide', 'Pyrazinamide', 'Pyrazinamide', 'Myrin-P Forte (fixed-dose combination)', 'Antituberculosis agent', 'Prescription', 'Pyrazinamide is a prodrug converted to pyrazinoic acid, which is active against semi-dormant M. tuberculosis in acidic environments; its exact mechanism is not fully understood. It is used during the 2-month intensive phase of first-line TB therapy, allowing total treatment to be shortened to 6 months.', 'Adults: 15-30 mg/kg orally once daily (maximum 2 g/day), or 50-75 mg/kg twice weekly based on lean body weight, always with other antituberculosis agents (typically for the first 2 months). Refer to current product labeling.', 'Adults: 15-30 mg/kg orally once daily (maximum 2 g/day), or 50-75 mg/kg twice weekly based on lean body weight, always with other antituberculosis agents (typically for the first 2 months). Refer to current product labeling.', 'Store at controlled room temperature 15-30 C (59-86 F) in a well-closed container.', 'Store at controlled room temperature 15-30 C (59-86 F) in a well-closed container.', NULL, 'pyrazinamide', 'FDA pyrazinamide tablet label via DailyMed; StatPearls: Antitubercular Medications; Goodman & Gilman''s 14th ed.', true),
    ('med_ethambutol', 'Ethambutol', 'Ethambutol hydrochloride', 'Myambutol', 'Antituberculosis agent', 'Prescription', 'Ethambutol inhibits mycobacterial arabinosyltransferases, interfering with arabinogalactan synthesis in the cell wall; it is bacteriostatic. It is included in the intensive phase of first-line TB therapy to protect against resistance while drug-susceptibility results are pending.', 'Adults: initial treatment 15 mg/kg orally once every 24 hours; retreatment 25 mg/kg once daily for 60 days, then 15 mg/kg once daily, always with other antituberculosis drugs. Dose reduction/extended interval (e.g., three times weekly when CrCl < 30 mL/min) is needed in renal impairment. Refer to current product labeling.', 'Adults: initial treatment 15 mg/kg orally once every 24 hours; retreatment 25 mg/kg once daily for 60 days, then 15 mg/kg once daily, always with other antituberculosis drugs. Dose reduction/extended interval (e.g., three times weekly when CrCl < 30 mL/min) is needed in renal impairment. Refer to current product labeling.', 'Store at 20-25 C (68-77 F).', 'Store at 20-25 C (68-77 F).', NULL, 'ethambutol', 'FDA Myambutol label via DailyMed; StatPearls: Ethambutol; Goodman & Gilman''s 14th ed.', true),
    ('med_artemether_lumefantrine', 'Artemether + Lumefantrine', 'Artemether + lumefantrine', 'Coartem', 'Antimalarial (artemisinin-based combination)', 'Prescription', 'Artemether (and its metabolite dihydroartemisinin) rapidly reduces parasite biomass, while the long-acting lumefantrine eliminates residual parasites; both are thought to interfere with parasite heme detoxification and nucleic acid/protein synthesis. This fixed-dose artemisinin-based combination therapy is a WHO-recommended first-line treatment for uncomplicated P. falciparum malaria.', 'Adults and patients >= 35 kg (20 mg/120 mg tablets): 4 tablets as an initial dose, 4 tablets again after 8 hours, then 4 tablets twice daily (morning and evening) for the following 2 days (total 6 doses, 24 tablets over 3 days). Take with food, ideally fat-containing, to enhance absorption; repeat the dose if vomiting occurs within 1-2 hours. Refer to current product labeling.', 'Adults and patients >= 35 kg (20 mg/120 mg tablets): 4 tablets as an initial dose, 4 tablets again after 8 hours, then 4 tablets twice daily (morning and evening) for the following 2 days (total 6 doses, 24 tablets over 3 days). Take with food, ideally fat-containing, to enhance absorption; repeat the dose if vomiting occurs within 1-2 hours. Refer to current product labeling.', 'Store at 25 C (77 F); excursions permitted to 15-30 C (59-86 F); dispense in a tight container.', 'Store at 25 C (77 F); excursions permitted to 15-30 C (59-86 F); dispense in a tight container.', NULL, 'artemether + lumefantrine', 'FDA Coartem label via DailyMed; WHO malaria guidelines (Nov 2022 update, via MMV); Goodman & Gilman''s 14th ed.', true),
    ('med_oseltamivir', 'Oseltamivir', 'Oseltamivir (as phosphate)', 'Tamiflu', 'Antiviral (neuraminidase inhibitor)', 'Prescription', 'Oseltamivir is an oral prodrug converted to oseltamivir carboxylate, a competitive inhibitor of influenza A and B neuraminidase that prevents release of new virions from infected cells. Started ideally within 48 hours of symptom onset, it shortens illness duration and is recommended for hospitalized and high-risk patients; it is also used for post-exposure prophylaxis.', 'Adults and adolescents >= 13 years: treatment 75 mg orally twice daily for 5 days (begin within 48 hours of symptom onset); prophylaxis 75 mg once daily for at least 10 days after exposure (up to 6 weeks during a community outbreak). Renal adjustment: CrCl > 30-60 mL/min 30 mg twice daily (treatment); CrCl > 10-30 mL/min 30 mg once daily (treatment); hemodialysis 30 mg after each dialysis cycle. Refer to current product labeling.', 'Adults and adolescents >= 13 years: treatment 75 mg orally twice daily for 5 days (begin within 48 hours of symptom onset); prophylaxis 75 mg once daily for at least 10 days after exposure (up to 6 weeks during a community outbreak). Renal adjustment: CrCl > 30-60 mL/min 30 mg twice daily (treatment); CrCl > 10-30 mL/min 30 mg once daily (treatment); hemodialysis 30 mg after each dialysis cycle. Refer to current product labeling.', 'Store capsules at 25 C (77 F); excursions permitted to 15-30 C (59-86 F).', 'Store capsules at 25 C (77 F); excursions permitted to 15-30 C (59-86 F).', NULL, 'oseltamivir', 'FDA Tamiflu label via DailyMed; StatPearls: Oseltamivir; Goodman & Gilman''s 14th ed.', true),
    ('med_nirmatrelvir_ritonavir', 'Nirmatrelvir + Ritonavir', 'Nirmatrelvir + Ritonavir (co-packaged tablets)', 'Paxlovid', 'Antiviral (SARS-CoV-2 protease inhibitor, ritonavir-boosted)', 'Prescription', 'Nirmatrelvir inhibits the SARS-CoV-2 main protease (Mpro), preventing viral polyprotein processing and replication. Ritonavir is a strong CYP3A inhibitor with no meaningful SARS-CoV-2 activity that is co-administered to raise nirmatrelvir plasma concentrations. It is used for mild-to-moderate COVID-19 in non-hospitalized patients at high risk of progression, started within 5 days of symptom onset.', 'Adults: nirmatrelvir 300 mg (two 150 mg tablets) + ritonavir 100 mg orally twice daily for 5 days, started within 5 days of symptom onset. eGFR 30 to <60 mL/min: nirmatrelvir 150 mg + ritonavir 100 mg twice daily for 5 days. eGFR <30 mL/min including hemodialysis: 300 mg/100 mg once on day 1, then 150 mg/100 mg once daily on days 2-5 (after dialysis on dialysis days). Not recommended in severe hepatic impairment (Child-Pugh C). Refer to current product labeling.', 'Adults: nirmatrelvir 300 mg (two 150 mg tablets) + ritonavir 100 mg orally twice daily for 5 days, started within 5 days of symptom onset. eGFR 30 to <60 mL/min: nirmatrelvir 150 mg + ritonavir 100 mg twice daily for 5 days. eGFR <30 mL/min including hemodialysis: 300 mg/100 mg once on day 1, then 150 mg/100 mg once daily on days 2-5 (after dialysis on dialysis days). Not recommended in severe hepatic impairment (Child-Pugh C). Refer to current product labeling.', 'Store at room temperature in the original blister packaging. Refer to current product labeling.', 'Store at room temperature in the original blister packaging. Refer to current product labeling.', 'Significant drug interactions: ritonavir is a strong CYP3A inhibitor and may increase exposure to co-administered drugs, leading to potentially severe, life-threatening or fatal events. Review all concomitant medications before prescribing and during therapy.', 'nirmatrelvir + ritonavir', 'FDA/DailyMed Paxlovid prescribing information; StatPearls: Nirmatrelvir-Ritonavir.', true),
    ('med_ors', 'Oral Rehydration Salts (reduced osmolarity)', 'Oral Rehydration Salts (reduced osmolarity, WHO/UNICEF formula)', 'Hydrite', 'Oral rehydration solution', 'OTC', 'Reduced-osmolarity ORS (245 mOsm/L) contains glucose and sodium in equimolar amounts (75 mmol/L each), exploiting sodium-glucose co-transport in the small intestine to drive water absorption even during secretory diarrhea. It also replaces potassium and corrects acidosis with citrate. Compared with the older standard ORS it reduces stool output, vomiting and the need for unscheduled IV therapy; it is the cornerstone of treatment for dehydration from acute diarrhea.', 'Composition per litre: sodium chloride 2.6 g, glucose anhydrous 13.5 g, potassium chloride 1.5 g, trisodium citrate dihydrate 2.9 g (Na 75, Cl 65, K 20, citrate 10, glucose 75 mmol/L; 245 mOsm/L). Reconstitute each sachet in the stated volume of clean drinking water. Adults, no dehydration (WHO Plan A): as much as wanted after each loose stool. Some dehydration (Plan B): about 75 mL/kg over 4 hours (adults 15 years and older: roughly 2200-4000 mL in the first 4 hours), then reassess. Severe dehydration requires IV rehydration (Plan C). Refer to current product labeling.', 'Composition per litre: sodium chloride 2.6 g, glucose anhydrous 13.5 g, potassium chloride 1.5 g, trisodium citrate dihydrate 2.9 g (Na 75, Cl 65, K 20, citrate 10, glucose 75 mmol/L; 245 mOsm/L). Reconstitute each sachet in the stated volume of clean drinking water. Adults, no dehydration (WHO Plan A): as much as wanted after each loose stool. Some dehydration (Plan B): about 75 mL/kg over 4 hours (adults 15 years and older: roughly 2200-4000 mL in the first 4 hours), then reassess. Severe dehydration requires IV rehydration (Plan C). Refer to current product labeling.', 'Store sachets in a cool, dry place. Use reconstituted solution within 24 hours and discard the remainder. Refer to current product labeling.', 'Store sachets in a cool, dry place. Use reconstituted solution within 24 hours and discard the remainder. Refer to current product labeling.', NULL, 'Oral rehydration salts', 'WHO/UNICEF Joint Statement: Clinical management of acute diarrhoea (2004); WHO Oral rehydration salts: production of the new ORS (2006); WHO The treatment of diarrhoea (2005).', true),
    ('med_loperamide', 'Loperamide', 'Loperamide hydrochloride', 'Imodium', 'Antidiarrheal (opioid receptor agonist)', 'OTC', 'Loperamide is a peripherally acting synthetic mu-opioid receptor agonist that slows intestinal transit and increases anal sphincter tone, reducing stool frequency and volume. At therapeutic doses P-glycoprotein efflux keeps it out of the CNS; at very high doses it crosses the blood-brain barrier and blocks cardiac sodium and potassium channels. It is used for symptomatic control of acute non-specific diarrhea and chronic diarrhea, not as a substitute for rehydration.', 'Adults, acute diarrhea: 4 mg initially, then 2 mg after each unformed stool. OTC maximum 8 mg/day; prescription maximum 16 mg/day. Chronic diarrhea: usual maintenance 4-8 mg/day (maximum 16 mg/day). Discontinue if no improvement within 48 hours of acute use or if constipation, abdominal distension or ileus develops. Maintain oral rehydration. Refer to current product labeling.', 'Adults, acute diarrhea: 4 mg initially, then 2 mg after each unformed stool. OTC maximum 8 mg/day; prescription maximum 16 mg/day. Chronic diarrhea: usual maintenance 4-8 mg/day (maximum 16 mg/day). Discontinue if no improvement within 48 hours of acute use or if constipation, abdominal distension or ileus develops. Maintain oral rehydration. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) in a well-closed container. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) in a well-closed container. Refer to current product labeling.', NULL, 'loperamide', 'DailyMed loperamide hydrochloride capsules prescribing information; StatPearls: Loperamide; Unilab Diatabs product information.', true),
    ('med_omeprazole', 'Omeprazole', 'Omeprazole (omeprazole magnesium)', 'Losec', 'Proton pump inhibitor', 'Prescription', 'Omeprazole irreversibly inhibits the parietal cell H+/K+-ATPase (proton pump), the final step of gastric acid secretion. Onset is within about an hour and acid suppression persists for up to 72 hours because new pumps must be synthesized. It is used for peptic ulcer disease, GERD and erosive esophagitis, Helicobacter pylori eradication regimens and hypersecretory states such as Zollinger-Ellison syndrome.', 'Adults, taken before a meal: active duodenal ulcer 20 mg once daily for 4 weeks; benign gastric ulcer 40 mg once daily for 4-8 weeks; symptomatic GERD 20 mg once daily up to 4 weeks; erosive esophagitis 20 mg once daily for 4-8 weeks, maintenance 20 mg once daily; H. pylori triple therapy 20 mg twice daily with amoxicillin and clarithromycin for 10 days; pathological hypersecretory conditions 60 mg once daily, adjusted to response. Hepatic impairment or Asian patients: 10 mg once daily for maintenance of healing of erosive esophagitis. Refer to current product labeling.', 'Adults, taken before a meal: active duodenal ulcer 20 mg once daily for 4 weeks; benign gastric ulcer 40 mg once daily for 4-8 weeks; symptomatic GERD 20 mg once daily up to 4 weeks; erosive esophagitis 20 mg once daily for 4-8 weeks, maintenance 20 mg once daily; H. pylori triple therapy 20 mg twice daily with amoxicillin and clarithromycin for 10 days; pathological hypersecretory conditions 60 mg once daily, adjusted to response. Hepatic impairment or Asian patients: 10 mg once daily for maintenance of healing of erosive esophagitis. Refer to current product labeling.', 'Store at room temperature, protected from moisture. Refer to current product labeling.', 'Store at room temperature, protected from moisture. Refer to current product labeling.', NULL, 'omeprazole', 'DailyMed Prilosec prescribing information (rev. 2024); StatPearls: Omeprazole.', true),
    ('med_amlodipine', 'Amlodipine', 'Amlodipine besylate', 'Norvasc', 'Calcium channel blocker (dihydropyridine)', 'Prescription', 'Amlodipine is a long-acting dihydropyridine calcium channel blocker that inhibits L-type calcium channels in vascular smooth muscle, causing arterial vasodilation and a fall in peripheral resistance and blood pressure. Its long half-life allows once-daily dosing. It is a first-line antihypertensive and is also used for chronic stable and vasospastic angina.', 'Adults: hypertension 5 mg once daily, maximum 10 mg once daily; coronary artery disease/angina 5-10 mg once daily. Small, fragile or elderly patients and those with hepatic insufficiency: start at 2.5 mg once daily and titrate slowly. Refer to current product labeling.', 'Adults: hypertension 5 mg once daily, maximum 10 mg once daily; coronary artery disease/angina 5-10 mg once daily. Small, fragile or elderly patients and those with hepatic insufficiency: start at 2.5 mg once daily and titrate slowly. Refer to current product labeling.', 'Store at controlled room temperature, 15-30 C (59-86 F). Refer to current product labeling.', 'Store at controlled room temperature, 15-30 C (59-86 F). Refer to current product labeling.', NULL, 'amlodipine', 'DailyMed Norvasc prescribing information; StatPearls: Amlodipine.', true),
    ('med_losartan', 'Losartan', 'Losartan potassium', 'Cozaar', 'Angiotensin receptor blocker (RAAS blocker)', 'Prescription', 'Losartan selectively blocks the angiotensin II type 1 (AT1) receptor, preventing angiotensin II-mediated vasoconstriction and aldosterone release. This lowers blood pressure and reduces intraglomerular pressure and proteinuria. It is used for hypertension (including with left ventricular hypertrophy) and diabetic nephropathy in type 2 diabetes, and does not cause the bradykinin-related cough typical of ACE inhibitors.', 'Adults: hypertension 50 mg once daily (25 mg if volume-depleted), up to 100 mg daily in one or two doses; type 2 diabetic nephropathy 50 mg once daily, increased to 100 mg once daily based on blood pressure. Mild-to-moderate hepatic impairment: start 25 mg once daily. Refer to current product labeling.', 'Adults: hypertension 50 mg once daily (25 mg if volume-depleted), up to 100 mg daily in one or two doses; type 2 diabetic nephropathy 50 mg once daily, increased to 100 mg once daily based on blood pressure. Mild-to-moderate hepatic impairment: start 25 mg once daily. Refer to current product labeling.', 'Store at 15-30 C (59-86 F); keep container tightly closed and protect from light. Refer to current product labeling.', 'Store at 15-30 C (59-86 F); keep container tightly closed and protect from light. Refer to current product labeling.', 'Fetal toxicity: drugs acting on the renin-angiotensin system cause injury and death to the developing fetus. Discontinue losartan as soon as pregnancy is detected.', 'losartan', 'DailyMed Cozaar prescribing information; StatPearls: Losartan; Unilab Lifezar product information.', true),
    ('med_enalapril', 'Enalapril', 'Enalapril maleate', 'Renitec', 'ACE inhibitor (RAAS blocker)', 'Prescription', 'Enalapril is a prodrug hydrolyzed to enalaprilat, which inhibits angiotensin-converting enzyme, lowering angiotensin II and aldosterone and increasing bradykinin. The result is vasodilation, reduced afterload and favorable cardiac remodeling. It is used for hypertension, heart failure with reduced ejection fraction and asymptomatic left ventricular dysfunction.', 'Adults: hypertension 5 mg once daily initially (2.5 mg if on a diuretic), usual 10-40 mg/day in one or two doses; heart failure 2.5 mg once daily initially, titrated to 2.5-20 mg twice daily (maximum 40 mg/day in divided doses). CrCl 30 mL/min or less (serum creatinine 3 mg/dL or more): start 2.5 mg once daily. Refer to current product labeling.', 'Adults: hypertension 5 mg once daily initially (2.5 mg if on a diuretic), usual 10-40 mg/day in one or two doses; heart failure 2.5 mg once daily initially, titrated to 2.5-20 mg twice daily (maximum 40 mg/day in divided doses). CrCl 30 mL/min or less (serum creatinine 3 mg/dL or more): start 2.5 mg once daily. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); keep container tightly closed and protect from moisture. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); keep container tightly closed and protect from moisture. Refer to current product labeling.', 'Fetal toxicity: drugs acting on the renin-angiotensin system cause injury and death to the developing fetus. Discontinue enalapril as soon as pregnancy is detected.', 'enalapril', 'DailyMed enalapril maleate tablets prescribing information; StatPearls: Enalapril.', true),
    ('med_hydrochlorothiazide', 'Hydrochlorothiazide', 'Hydrochlorothiazide', 'Microzide', 'Thiazide diuretic', 'Prescription', 'Hydrochlorothiazide inhibits the Na+/Cl- cotransporter in the distal convoluted tubule, increasing sodium and water excretion. Blood pressure falls initially from volume reduction and long-term from reduced peripheral vascular resistance. It is used alone or in combination for hypertension and for edema, and is less effective when renal function is severely reduced.', 'Adults: hypertension 12.5-25 mg once daily, titrated to a maximum of 50 mg daily (little added benefit above 25 mg; doses above 50 mg cause marked potassium loss); edema 25-100 mg daily in single or divided doses. Refer to current product labeling.', 'Adults: hypertension 12.5-25 mg once daily, titrated to a maximum of 50 mg daily (little added benefit above 25 mg; doses above 50 mg cause marked potassium loss); edema 25-100 mg daily in single or divided doses. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); protect from light and moisture. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); protect from light and moisture. Refer to current product labeling.', NULL, 'hydrochlorothiazide', 'DailyMed hydrochlorothiazide tablets prescribing information; StatPearls: Hydrochlorothiazide.', true),
    ('med_furosemide', 'Furosemide', 'Furosemide', 'Lasix', 'Loop diuretic', 'Prescription', 'Furosemide inhibits the Na+/K+/2Cl- cotransporter in the thick ascending limb of the loop of Henle, producing a potent, short-acting diuresis with loss of sodium, chloride, potassium, magnesium and water. It remains effective at low GFR. It is used for edema from heart failure, cirrhosis and renal disease, and for hypertension, particularly when renal function is reduced.', 'Adults (oral): edema 20-80 mg as a single dose; repeat or increase by 20-40 mg no sooner than 6-8 hours after the previous dose until the desired diuresis (doses up to 600 mg/day in severe edematous states under close supervision). Hypertension: usually 80 mg/day, often as 40 mg twice daily, adjusted to response. Refer to current product labeling.', 'Adults (oral): edema 20-80 mg as a single dose; repeat or increase by 20-40 mg no sooner than 6-8 hours after the previous dose until the desired diuresis (doses up to 600 mg/day in severe edematous states under close supervision). Hypertension: usually 80 mg/day, often as 40 mg twice daily, adjusted to response. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); excursions permitted to 15-30 C. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); excursions permitted to 15-30 C. Refer to current product labeling.', 'Furosemide is a potent diuretic which, if given in excessive amounts, can lead to profound diuresis with water and electrolyte depletion; careful medical supervision and individualized dosing are required.', 'furosemide', 'DailyMed Lasix prescribing information; StatPearls: Furosemide.', true),
    ('med_spironolactone', 'Spironolactone', 'Spironolactone', 'Aldactone', 'Potassium-sparing diuretic (mineralocorticoid receptor antagonist)', 'Prescription', 'Spironolactone competitively blocks the mineralocorticoid (aldosterone) receptor in the distal nephron, increasing sodium and water excretion while retaining potassium. It also has anti-androgenic activity. It reduces mortality in heart failure with reduced ejection fraction and is used for resistant hypertension, primary hyperaldosteronism and edema from cirrhosis or nephrotic syndrome.', 'Adults: heart failure (NYHA III-IV) 25 mg once daily, increased to 50 mg daily if tolerated (reduce to 25 mg every other day if hyperkalemia); hypertension 25-100 mg/day in single or divided doses, titrated at 2-week intervals; edema (cirrhosis, nephrotic syndrome) 100 mg/day initially (cirrhosis: start in hospital); primary hyperaldosteronism 100-400 mg/day. Refer to current product labeling.', 'Adults: heart failure (NYHA III-IV) 25 mg once daily, increased to 50 mg daily if tolerated (reduce to 25 mg every other day if hyperkalemia); hypertension 25-100 mg/day in single or divided doses, titrated at 2-week intervals; edema (cirrhosis, nephrotic syndrome) 100 mg/day initially (cirrhosis: start in hospital); primary hyperaldosteronism 100-400 mg/day. Refer to current product labeling.', 'Store below 25 C (77 F). Refer to current product labeling.', 'Store below 25 C (77 F). Refer to current product labeling.', NULL, 'spironolactone', 'DailyMed Aldactone prescribing information; StatPearls: Spironolactone.', true),
    ('med_metoprolol', 'Metoprolol', 'Metoprolol tartrate / metoprolol succinate', 'Betaloc', 'Beta-blocker (beta-1 selective)', 'Prescription', 'Metoprolol is a relatively cardioselective beta-1 adrenergic receptor antagonist that reduces heart rate, contractility and blood pressure and lowers myocardial oxygen demand. Selectivity is dose-dependent and is lost at higher doses. It is used for hypertension, angina, secondary prevention after myocardial infarction, and (as the succinate extended-release form) heart failure with reduced ejection fraction.', 'Adults (metoprolol tartrate): hypertension 100 mg/day in single or divided doses initially, effective range 100-450 mg/day; angina 100 mg/day in two divided doses, range 100-400 mg/day; post-MI maintenance 100 mg twice daily. Heart failure uses metoprolol succinate extended-release started at a low dose and titrated to a target of 100-200 mg once daily. Hepatic impairment: start low and titrate gradually. Do not stop abruptly; taper over 1-2 weeks. Refer to current product labeling.', 'Adults (metoprolol tartrate): hypertension 100 mg/day in single or divided doses initially, effective range 100-450 mg/day; angina 100 mg/day in two divided doses, range 100-400 mg/day; post-MI maintenance 100 mg twice daily. Heart failure uses metoprolol succinate extended-release started at a low dose and titrated to a target of 100-200 mg once daily. Hepatic impairment: start low and titrate gradually. Do not stop abruptly; taper over 1-2 weeks. Refer to current product labeling.', 'Store at 25 C (77 F); excursions permitted to 15-30 C. Protect from moisture and heat. Refer to current product labeling.', 'Store at 25 C (77 F); excursions permitted to 15-30 C. Protect from moisture and heat. Refer to current product labeling.', 'Ischemic heart disease: abrupt cessation can cause severe exacerbation of angina, myocardial infarction and ventricular arrhythmias; taper over 1-2 weeks. This is a boxed warning in metoprolol labeling cited by StatPearls; the current Lopressor label lists it as a warning.', 'metoprolol', 'DailyMed Lopressor prescribing information; StatPearls: Metoprolol.', true),
    ('med_atorvastatin', 'Atorvastatin', 'Atorvastatin calcium', 'Lipitor', 'Statin (HMG-CoA reductase inhibitor)', 'Prescription', 'Atorvastatin competitively inhibits HMG-CoA reductase, the rate-limiting enzyme of hepatic cholesterol synthesis, which up-regulates hepatic LDL receptors and lowers LDL-cholesterol. Moderate-intensity doses (10-20 mg) lower LDL-C by about 30-50% and high-intensity doses (40-80 mg) by more than 50%. It reduces the risk of MI, stroke and revascularization in primary and secondary prevention.', 'Adults: 10-80 mg once daily at any time of day; usual starting dose 10-20 mg (40 mg if a large LDL-C reduction is needed). Dose caps with interacting drugs: do not exceed 20 mg/day with clarithromycin, itraconazole or several ritonavir-boosted protease inhibitors; 40 mg/day with nelfinavir; avoid with cyclosporine, gemfibrozil and tipranavir/ritonavir. Refer to current product labeling.', 'Adults: 10-80 mg once daily at any time of day; usual starting dose 10-20 mg (40 mg if a large LDL-C reduction is needed). Dose caps with interacting drugs: do not exceed 20 mg/day with clarithromycin, itraconazole or several ritonavir-boosted protease inhibitors; 40 mg/day with nelfinavir; avoid with cyclosporine, gemfibrozil and tipranavir/ritonavir. Refer to current product labeling.', 'Store at controlled room temperature 20-25 C (68-77 F). Refer to current product labeling.', 'Store at controlled room temperature 20-25 C (68-77 F). Refer to current product labeling.', NULL, 'atorvastatin', 'FDA Lipitor prescribing information (2024); StatPearls: Atorvastatin.', true),
    ('med_dapagliflozin', 'Dapagliflozin', 'Dapagliflozin (propanediol)', 'Forxiga', 'SGLT2 inhibitor', 'Prescription', 'Dapagliflozin inhibits the sodium-glucose cotransporter 2 in the proximal renal tubule, reducing glucose reabsorption and increasing urinary glucose excretion independent of insulin. It also causes natriuresis and osmotic diuresis, lowers blood pressure and reduces intraglomerular pressure. It is used for type 2 diabetes and, independent of diabetes status, to reduce cardiovascular and kidney outcomes in heart failure and chronic kidney disease.', 'Adults: glycemic control 5 mg once daily, may increase to 10 mg once daily; heart failure and chronic kidney disease 10 mg once daily. Not recommended for glycemic control if eGFR <45 mL/min/1.73 m2. Initiation not recommended if eGFR <25; may continue if eGFR falls below 25 during treatment. Withhold at least 3 days before scheduled surgery or prolonged fasting. Refer to current product labeling.', 'Adults: glycemic control 5 mg once daily, may increase to 10 mg once daily; heart failure and chronic kidney disease 10 mg once daily. Not recommended for glycemic control if eGFR <45 mL/min/1.73 m2. Initiation not recommended if eGFR <25; may continue if eGFR falls below 25 during treatment. Withhold at least 3 days before scheduled surgery or prolonged fasting. Refer to current product labeling.', 'Store at room temperature. Refer to current product labeling.', 'Store at room temperature. Refer to current product labeling.', NULL, 'dapagliflozin', 'DailyMed Farxiga prescribing information; StatPearls: SGLT2 Inhibitors.', true),
    ('med_metformin', 'Metformin', 'Metformin hydrochloride', 'Glucophage', 'Biguanide antidiabetic', 'Prescription', 'Metformin lowers blood glucose mainly by decreasing hepatic gluconeogenesis, and also reduces intestinal glucose absorption and improves peripheral insulin sensitivity. It does not stimulate insulin secretion, so it rarely causes hypoglycemia alone and is weight-neutral. It is the usual first-line oral agent for type 2 diabetes.', 'Adults (immediate-release): start 500 mg twice daily or 850 mg once daily with meals; increase by 500 mg weekly or 850 mg every 2 weeks; maximum 2550 mg/day in divided doses (doses above 2000 mg may be better tolerated three times daily). Extended-release: 500-1000 mg once daily with the evening meal, maximum 2000 mg/day. Contraindicated if eGFR <30; initiation not recommended at eGFR 30-45. Hold for iodinated contrast procedures in at-risk patients and re-check eGFR 48 hours after. Refer to current product labeling.', 'Adults (immediate-release): start 500 mg twice daily or 850 mg once daily with meals; increase by 500 mg weekly or 850 mg every 2 weeks; maximum 2550 mg/day in divided doses (doses above 2000 mg may be better tolerated three times daily). Extended-release: 500-1000 mg once daily with the evening meal, maximum 2000 mg/day. Contraindicated if eGFR <30; initiation not recommended at eGFR 30-45. Hold for iodinated contrast procedures in at-risk patients and re-check eGFR 48 hours after. Refer to current product labeling.', 'Store at 20-25 C (68-77 F). Refer to current product labeling.', 'Store at 20-25 C (68-77 F). Refer to current product labeling.', 'Lactic acidosis: postmarketing cases of metformin-associated lactic acidosis have resulted in death, hypothermia, hypotension and resistant bradyarrhythmias. Risk factors include renal impairment, age 65 or older, iodinated contrast, surgery, hypoxic states, excessive alcohol intake and hepatic impairment. Discontinue immediately and hospitalize if lactic acidosis is suspected.', 'metformin', 'DailyMed metformin hydrochloride tablets prescribing information; StatPearls: Metformin.', true),
    ('med_gliclazide', 'Gliclazide', 'Gliclazide', 'Diamicron MR', 'Sulfonylurea antidiabetic', 'Prescription', 'Gliclazide is a second-generation sulfonylurea that binds the SUR1 subunit of ATP-sensitive potassium channels on pancreatic beta cells, causing depolarization, calcium influx and insulin release regardless of blood glucose level. Hypoglycemia and weight gain are the main drawbacks. It is used in type 2 diabetes when metformin alone is insufficient or not tolerated; it is not marketed in the United States.', 'Adults, modified-release (MR): 30 mg once daily with breakfast, increased stepwise (at intervals of at least 1 month, or 2 weeks if glucose is not reduced) to a maximum of 120 mg once daily. Immediate-release: 40-80 mg daily initially, up to 320 mg/day (doses above 160 mg in two divided doses). Refer to current product labeling.', 'Adults, modified-release (MR): 30 mg once daily with breakfast, increased stepwise (at intervals of at least 1 month, or 2 weeks if glucose is not reduced) to a maximum of 120 mg once daily. Immediate-release: 40-80 mg daily initially, up to 320 mg/day (doses above 160 mg in two divided doses). Refer to current product labeling.', 'No special storage conditions (per SmPC). Refer to current product labeling.', 'No special storage conditions (per SmPC). Refer to current product labeling.', NULL, 'gliclazide', 'Diamicron 30 mg MR SmPC (electronic Medicines Compendium, UK); StatPearls: Sulfonylureas.', true),
    ('med_salbutamol', 'Salbutamol (Albuterol)', 'Salbutamol sulfate (albuterol sulfate)', 'Ventolin', 'Short-acting beta-2 agonist (bronchodilator)', 'Prescription', 'Salbutamol stimulates beta-2 adrenergic receptors on bronchial smooth muscle, activating adenylyl cyclase and relaxing the airways within minutes, with effects lasting 4-6 hours. It also inhibits mediator release from mast cells. It is used for relief and prevention of bronchospasm in asthma, COPD and exercise-induced bronchoconstriction.', 'Adults (metered-dose inhaler): 2 inhalations every 4-6 hours as needed (1 inhalation every 4 hours may suffice); exercise-induced bronchospasm: 2 inhalations 15-30 minutes before exercise. Increasing need for the reliever indicates deteriorating control and requires review; do not exceed labeled frequency without medical evaluation. Refer to current product labeling.', 'Adults (metered-dose inhaler): 2 inhalations every 4-6 hours as needed (1 inhalation every 4 hours may suffice); exercise-induced bronchospasm: 2 inhalations 15-30 minutes before exercise. Increasing need for the reliever indicates deteriorating control and requires review; do not exceed labeled frequency without medical evaluation. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) with the mouthpiece down. Pressurized canister: do not puncture, incinerate or expose to heat. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) with the mouthpiece down. Pressurized canister: do not puncture, incinerate or expose to heat. Refer to current product labeling.', NULL, 'salbutamol', 'DailyMed Ventolin HFA prescribing information; StatPearls: Albuterol.', true),
    ('med_budesonide_formoterol', 'Budesonide + Formoterol', 'Budesonide + Formoterol fumarate dihydrate', 'Symbicort', 'Inhaled corticosteroid + long-acting beta-2 agonist', 'Prescription', 'Budesonide is an inhaled glucocorticoid that suppresses airway inflammation, and formoterol is a long-acting beta-2 agonist with a rapid onset of bronchodilation. The combination provides maintenance control of asthma and COPD. Because formoterol acts quickly, GINA also recommends budesonide-formoterol as an as-needed anti-inflammatory reliever and for maintenance-and-reliever therapy in asthma, whereas US labeling covers maintenance use only.', 'Adults and adolescents 12 years and older, asthma (US label): 2 inhalations of 80/4.5 mcg or 160/4.5 mcg twice daily; COPD: 2 inhalations of 160/4.5 mcg twice daily. Rinse mouth with water (without swallowing) after use. Not for primary treatment of acute bronchospasm under US labeling; do not use with other LABAs. Refer to current product labeling.', 'Adults and adolescents 12 years and older, asthma (US label): 2 inhalations of 80/4.5 mcg or 160/4.5 mcg twice daily; COPD: 2 inhalations of 160/4.5 mcg twice daily. Rinse mouth with water (without swallowing) after use. Not for primary treatment of acute bronchospasm under US labeling; do not use with other LABAs. Refer to current product labeling.', 'Store at room temperature with the mouthpiece down; pressurized canister - do not puncture, incinerate or expose to heat. Prime before first use and after 7 or more days of non-use. Refer to current product labeling.', 'Store at room temperature with the mouthpiece down; pressurized canister - do not puncture, incinerate or expose to heat. Prime before first use and after 7 or more days of non-use. Refer to current product labeling.', NULL, 'budesonide + formoterol', 'DailyMed Symbicort prescribing information; GINA (as-needed/maintenance-and-reliever use).', true),
    ('med_prednisone', 'Prednisone', 'Prednisone', 'Rayos', 'Corticosteroid (systemic glucocorticoid)', 'Prescription', 'Prednisone is an oral synthetic glucocorticoid prodrug converted in the liver to prednisolone. It binds glucocorticoid receptors and alters gene transcription, producing potent anti-inflammatory and immunosuppressive effects. It is used across endocrine, rheumatic, collagen-vascular, dermatologic, allergic (including asthma exacerbations), respiratory, hematologic, neoplastic and gastrointestinal inflammatory disorders.', 'Adults: initial dose 5-60 mg/day depending on the disease and severity, individualized and maintained until an adequate response, then reduced gradually to the lowest effective maintenance dose. After prolonged therapy withdraw gradually to avoid adrenal insufficiency. Refer to current product labeling.', 'Adults: initial dose 5-60 mg/day depending on the disease and severity, individualized and maintained until an adequate response, then reduced gradually to the lowest effective maintenance dose. After prolonged therapy withdraw gradually to avoid adrenal insufficiency. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) in a tight, light-resistant container. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) in a tight, light-resistant container. Refer to current product labeling.', NULL, 'prednisone', 'DailyMed prednisone tablets prescribing information.', true),
    ('med_sumatriptan', 'Sumatriptan', 'Sumatriptan succinate', 'Imigran', 'Triptan (5-HT1B/1D agonist)', 'Prescription', 'Sumatriptan is a selective serotonin 5-HT1B/1D receptor agonist that constricts dilated cranial blood vessels and inhibits release of vasoactive neuropeptides and pain transmission in the trigeminal system. It is an abortive (acute) treatment and does not prevent migraine attacks. It is used for acute migraine with or without aura and, subcutaneously, for cluster headache.', 'Adults (oral): 25, 50 or 100 mg as a single dose at onset; if headache returns or partial response, a second dose may be taken at least 2 hours later; maximum 200 mg in 24 hours. Subcutaneous: up to 6 mg, may repeat after at least 1 hour, maximum 12 mg/24 hours. Mild-to-moderate hepatic impairment: maximum single oral dose 50 mg. Use on 10 or more days per month risks medication overuse headache. Refer to current product labeling.', 'Adults (oral): 25, 50 or 100 mg as a single dose at onset; if headache returns or partial response, a second dose may be taken at least 2 hours later; maximum 200 mg in 24 hours. Subcutaneous: up to 6 mg, may repeat after at least 1 hour, maximum 12 mg/24 hours. Mild-to-moderate hepatic impairment: maximum single oral dose 50 mg. Use on 10 or more days per month risks medication overuse headache. Refer to current product labeling.', 'Store between 2-30 C (36-86 F). Refer to current product labeling.', 'Store between 2-30 C (36-86 F). Refer to current product labeling.', NULL, 'sumatriptan', 'DailyMed Imitrex tablets prescribing information; StatPearls: Sumatriptan.', true),
    ('med_tenofovir', 'Tenofovir Disoproxil Fumarate', 'Tenofovir disoproxil fumarate (TDF)', 'Tenofo B', 'Antiviral (nucleotide reverse transcriptase inhibitor)', 'Prescription', 'Tenofovir disoproxil fumarate is an oral prodrug of tenofovir, an acyclic nucleotide (adenosine monophosphate) analogue. After intracellular phosphorylation to tenofovir diphosphate it competes with natural nucleotides and terminates DNA chain elongation, inhibiting HIV-1 reverse transcriptase and the hepatitis B virus polymerase. It is used with other antiretrovirals for HIV-1 treatment, as HIV pre-exposure prophylaxis with emtricitabine, and as a first-line agent for chronic hepatitis B because of its high barrier to resistance.', 'Adults and pediatric patients weighing at least 35 kg (HIV-1 infection, in combination with other antiretrovirals; chronic hepatitis B): 300 mg orally once daily, with or without food. Renal impairment (adults): CrCl 30-49 mL/min, 300 mg every 48 hours; CrCl 10-29 mL/min, 300 mg every 72-96 hours; hemodialysis, 300 mg every 7 days or after a total of about 12 hours of dialysis; no dosing recommendation is available for CrCl < 10 mL/min without hemodialysis. Serum creatinine, estimated creatinine clearance, urine glucose and urine protein are assessed before and during therapy, with serum phosphorus in chronic kidney disease. Refer to current product labeling.', 'Adults and pediatric patients weighing at least 35 kg (HIV-1 infection, in combination with other antiretrovirals; chronic hepatitis B): 300 mg orally once daily, with or without food. Renal impairment (adults): CrCl 30-49 mL/min, 300 mg every 48 hours; CrCl 10-29 mL/min, 300 mg every 72-96 hours; hemodialysis, 300 mg every 7 days or after a total of about 12 hours of dialysis; no dosing recommendation is available for CrCl < 10 mL/min without hemodialysis. Serum creatinine, estimated creatinine clearance, urine glucose and urine protein are assessed before and during therapy, with serum phosphorus in chronic kidney disease. Refer to current product labeling.', 'Store at room temperature as directed on the product labeling.', 'Store at room temperature as directed on the product labeling.', 'Severe acute exacerbation of hepatitis B: severe acute exacerbations of hepatitis B have been reported in HBV-infected patients who have discontinued anti-hepatitis B therapy, including tenofovir disoproxil fumarate. Hepatic function is monitored closely with clinical and laboratory follow-up for at least several months after discontinuation; resumption of anti-hepatitis B therapy may be warranted.', 'tenofovir disoproxil', 'VIREAD (tenofovir disoproxil fumarate) FDA label via DailyMed; StatPearls: Reverse Transcriptase Inhibitors; StatPearls: HIV and AIDS; StatPearls: Hepatitis B; Goodman & Gilman''s 14th ed.', true),
    ('med_entecavir', 'Entecavir', 'Entecavir', 'Entegard', 'Antiviral (nucleoside analogue, HBV polymerase inhibitor)', 'Prescription', 'Entecavir is a guanosine nucleoside analogue that is phosphorylated intracellularly to its active triphosphate, which competes with deoxyguanosine triphosphate and inhibits all three activities of the hepatitis B virus polymerase (base priming, reverse transcription of the negative strand and synthesis of the positive strand). It is a preferred first-line oral agent for chronic hepatitis B because of its potency and high barrier to resistance in nucleoside-naive patients.', 'Adults (chronic hepatitis B): nucleoside-inhibitor-treatment-naive with compensated liver disease, 0.5 mg orally once daily; lamivudine-refractory or known lamivudine/telbivudine resistance, 1 mg once daily; decompensated liver disease, 1 mg once daily. Take on an empty stomach (at least 2 hours after a meal and 2 hours before the next meal). Renal impairment (usual 0.5 mg dose): CrCl 30 to < 50 mL/min, 0.25 mg once daily or 0.5 mg every 48 hours; CrCl 10 to < 30, 0.15 mg once daily or 0.5 mg every 72 hours; CrCl < 10, hemodialysis or CAPD, 0.05 mg once daily or 0.5 mg every 7 days (give after hemodialysis); the 1 mg regimens are adjusted proportionally. No dose adjustment for hepatic impairment. Refer to current product labeling.', 'Adults (chronic hepatitis B): nucleoside-inhibitor-treatment-naive with compensated liver disease, 0.5 mg orally once daily; lamivudine-refractory or known lamivudine/telbivudine resistance, 1 mg once daily; decompensated liver disease, 1 mg once daily. Take on an empty stomach (at least 2 hours after a meal and 2 hours before the next meal). Renal impairment (usual 0.5 mg dose): CrCl 30 to < 50 mL/min, 0.25 mg once daily or 0.5 mg every 48 hours; CrCl 10 to < 30, 0.15 mg once daily or 0.5 mg every 72 hours; CrCl < 10, hemodialysis or CAPD, 0.05 mg once daily or 0.5 mg every 7 days (give after hemodialysis); the 1 mg regimens are adjusted proportionally. No dose adjustment for hepatic impairment. Refer to current product labeling.', 'Store tablets at 20-25 C (68-77 F), excursions permitted to 15-30 C, in a tightly closed container protected from light.', 'Store tablets at 20-25 C (68-77 F), excursions permitted to 15-30 C, in a tightly closed container protected from light.', 'Severe acute exacerbations of hepatitis B have been reported in patients who discontinued anti-hepatitis B therapy, including entecavir; hepatic function is monitored closely for at least several months after discontinuation. Patients coinfected with HIV and HBV: entecavir is not recommended for HBV in coinfected patients not also receiving highly active antiretroviral therapy because of the risk of HIV-1 resistance. Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with nucleoside analogues.', 'entecavir', 'BARACLUDE (entecavir) FDA label via DailyMed; StatPearls: Hepatitis B; Goodman & Gilman''s 14th ed.', true),
    ('med_tld', 'Tenofovir + Lamivudine + Dolutegravir (TLD)', 'Tenofovir disoproxil fumarate 300 mg + lamivudine 300 mg + dolutegravir 50 mg', '', 'Antiretroviral (NRTI + integrase inhibitor fixed-dose combination)', 'Prescription', 'TLD is a once-daily fixed-dose tablet combining two nucleos(t)ide reverse transcriptase inhibitors (tenofovir disoproxil fumarate and lamivudine), which terminate viral DNA chain synthesis, with dolutegravir, an integrase strand transfer inhibitor that blocks integration of HIV DNA into the host genome. WHO recommends dolutegravir-based therapy as the preferred first- and second-line HIV treatment in all populations, and tenofovir plus lamivudine also suppress hepatitis B virus. There is no US boxed warning for this WHO-prequalified combination itself, but the US label of its tenofovir disoproxil component carries a boxed warning for severe acute exacerbation of hepatitis B after discontinuation, which applies to people with HBV co-infection. In the Philippines it is the DOH''s recommended first-line antiretroviral regimen, procured nationally for people living with HIV (Philippine News Agency, July 2026).', 'Adults and adolescents weighing at least 30 kg: one tablet (dolutegravir 50 mg / lamivudine 300 mg / tenofovir disoproxil fumarate 300 mg) orally once daily, with or without food. With rifampicin, the dolutegravir dose is increased to 50 mg twice daily (an additional dolutegravir 50 mg tablet about 12 hours after TLD). Not recommended when CrCl < 50 mL/min (use separate components with dose adjustment). No dose adjustment for mild or moderate hepatic impairment; caution in severe hepatic impairment. Refer to current product labeling.', 'Adults and adolescents weighing at least 30 kg: one tablet (dolutegravir 50 mg / lamivudine 300 mg / tenofovir disoproxil fumarate 300 mg) orally once daily, with or without food. With rifampicin, the dolutegravir dose is increased to 50 mg twice daily (an additional dolutegravir 50 mg tablet about 12 hours after TLD). Not recommended when CrCl < 50 mL/min (use separate components with dose adjustment). No dose adjustment for mild or moderate hepatic impairment; caution in severe hepatic impairment. Refer to current product labeling.', 'Store as directed on the product labeling.', 'Store as directed on the product labeling.', NULL, 'dolutegravir + lamivudine + tenofovir disoproxil', 'WHO Public Assessment Report (WHOPAR) product information for dolutegravir/lamivudine/tenofovir disoproxil 50/300/300 mg; WHO news release 22 July 2019 (dolutegravir preferred in all populations); TIVICAY (dolutegravir) FDA label via DailyMed; NIH Adult and Adolescent ARV Guidelines drug-interaction tables; StatPearls: HIV and AIDS; Goodman & Gilman''s 14th ed; DOH via Philippine News Agency (2026)', true),
    ('med_cotrimoxazole', 'Co-trimoxazole (Sulfamethoxazole + Trimethoprim)', 'Sulfamethoxazole + Trimethoprim (co-trimoxazole)', 'Combizole', 'Antibiotic (sulfonamide + dihydrofolate reductase inhibitor)', 'Prescription', 'Co-trimoxazole combines sulfamethoxazole, which inhibits dihydropteroate synthase and blocks bacterial use of para-aminobenzoic acid, with trimethoprim, which inhibits dihydrofolate reductase. Sequential blockade of folate synthesis gives a synergistic, often bactericidal effect. It is used for urinary tract infections, shigellosis, traveler''s diarrhea, exacerbations of chronic bronchitis, and for treatment and prophylaxis of Pneumocystis jirovecii pneumonia and toxoplasmosis.', 'Adults (sulfamethoxazole/trimethoprim): urinary tract infection, 800/160 mg (one double-strength tablet or two single-strength tablets) every 12 hours for 10-14 days; shigellosis, 800/160 mg every 12 hours for 5 days; traveler''s diarrhea, 800/160 mg every 12 hours for 5 days; acute exacerbation of chronic bronchitis, 800/160 mg every 12 hours for 10-14 days; Pneumocystis jirovecii pneumonia treatment, 75-100 mg/kg/day sulfamethoxazole plus 15-20 mg/kg/day trimethoprim in divided doses every 6 hours for 14-21 days; P. jirovecii prophylaxis, one double-strength tablet daily. Renal impairment: CrCl > 30 mL/min usual regimen; 15-30 mL/min half the usual regimen; < 15 mL/min not recommended. Maintain adequate fluid intake to prevent crystalluria. Refer to current product labeling.', 'Adults (sulfamethoxazole/trimethoprim): urinary tract infection, 800/160 mg (one double-strength tablet or two single-strength tablets) every 12 hours for 10-14 days; shigellosis, 800/160 mg every 12 hours for 5 days; traveler''s diarrhea, 800/160 mg every 12 hours for 5 days; acute exacerbation of chronic bronchitis, 800/160 mg every 12 hours for 10-14 days; Pneumocystis jirovecii pneumonia treatment, 75-100 mg/kg/day sulfamethoxazole plus 15-20 mg/kg/day trimethoprim in divided doses every 6 hours for 14-21 days; P. jirovecii prophylaxis, one double-strength tablet daily. Renal impairment: CrCl > 30 mL/min usual regimen; 15-30 mL/min half the usual regimen; < 15 mL/min not recommended. Maintain adequate fluid intake to prevent crystalluria. Refer to current product labeling.', 'Store at 20-25 C (68-77 F) in a tight, light-resistant container.', 'Store at 20-25 C (68-77 F) in a tight, light-resistant container.', NULL, 'sulfamethoxazole + trimethoprim', 'BACTRIM / BACTRIM DS FDA label via DailyMed; StatPearls: Trimethoprim-Sulfamethoxazole; Goodman & Gilman''s 14th ed.', true),
    ('med_praziquantel', 'Praziquantel', 'Praziquantel', '', 'Anthelmintic (pyrazinoisoquinoline)', 'Prescription', 'Praziquantel is a synthetic pyrazinoisoquinoline anthelmintic that increases the permeability of the helminth tegument to calcium, producing rapid muscle contraction, spastic paralysis and tegumental damage that exposes the parasite to host defenses. It is the drug of choice for all Schistosoma species, including S. japonicum endemic in the Philippines, and for the liver flukes Clonorchis and Opisthorchis, and is also active against tapeworms and cysticercosis.', 'Adults and children 1 year and older: schistosomiasis, 20 mg/kg three times in one day, doses 4-6 hours apart (60 mg/kg/day; StatPearls cites 40 mg/kg/day for S. mansoni, S. haematobium and S. intercalatum and 60 mg/kg/day for S. japonicum and S. mekongi); clonorchiasis/opisthorchiasis, 25 mg/kg three times in one day, 4-6 hours apart. Taeniasis (off-label): 5-10 mg/kg as a single dose. Strong CYP3A inducers such as rifampicin are stopped 2-4 weeks before praziquantel and may be restarted 1 day after completing treatment. No renal dose adjustment. Driving or operating machinery is avoided on the day of treatment and the following day. Refer to current product labeling.', 'Adults and children 1 year and older: schistosomiasis, 20 mg/kg three times in one day, doses 4-6 hours apart (60 mg/kg/day; StatPearls cites 40 mg/kg/day for S. mansoni, S. haematobium and S. intercalatum and 60 mg/kg/day for S. japonicum and S. mekongi); clonorchiasis/opisthorchiasis, 25 mg/kg three times in one day, 4-6 hours apart. Taeniasis (off-label): 5-10 mg/kg as a single dose. Strong CYP3A inducers such as rifampicin are stopped 2-4 weeks before praziquantel and may be restarted 1 day after completing treatment. No renal dose adjustment. Driving or operating machinery is avoided on the day of treatment and the following day. Refer to current product labeling.', 'Store below 30 C (86 F).', 'Store below 30 C (86 F).', NULL, 'praziquantel', 'BILTRICIDE (praziquantel) FDA label via DailyMed; StatPearls: Antiparasitic Drugs; Philippine News Agency report on the DOH schistosomiasis program; Goodman & Gilman''s 14th ed.', true),
    ('med_aciclovir', 'Aciclovir', 'Aciclovir (acyclovir)', 'Zovirax', 'Antiviral (nucleoside analogue, herpesvirus DNA polymerase inhibitor)', 'Prescription', 'Aciclovir is a synthetic purine (guanosine) nucleoside analogue that is phosphorylated by viral and host cellular enzymes to aciclovir triphosphate, which inhibits herpesvirus DNA polymerase and terminates viral DNA chain elongation. Its selectivity for infected cells makes it active against herpes simplex virus types 1 and 2 and varicella-zoster virus. It is used for genital and mucocutaneous herpes, herpes zoster, varicella and, intravenously, herpes simplex encephalitis.', 'Adults (oral): initial genital herpes, 200 mg every 4 hours five times daily for 10 days; chronic suppression of recurrent genital herpes, 400 mg twice daily for up to 12 months; herpes zoster, 800 mg every 4 hours five times daily for 7-10 days; varicella, 800 mg four times daily for 5 days. HSV encephalitis (IV): 10 mg/kg every 8 hours for 21 days, dosed on ideal body weight. Renal impairment (oral): 800 mg regimen, CrCl 10-25 mL/min/1.73 m2 every 8 hours and 0-10 every 12 hours; 200 mg regimen, CrCl 0-10 every 12 hours; 400 mg twice-daily regimen, CrCl 0-10, 200 mg every 12 hours. Adequate hydration is maintained. Refer to current product labeling.', 'Adults (oral): initial genital herpes, 200 mg every 4 hours five times daily for 10 days; chronic suppression of recurrent genital herpes, 400 mg twice daily for up to 12 months; herpes zoster, 800 mg every 4 hours five times daily for 7-10 days; varicella, 800 mg four times daily for 5 days. HSV encephalitis (IV): 10 mg/kg every 8 hours for 21 days, dosed on ideal body weight. Renal impairment (oral): 800 mg regimen, CrCl 10-25 mL/min/1.73 m2 every 8 hours and 0-10 every 12 hours; 200 mg regimen, CrCl 0-10 every 12 hours; 400 mg twice-daily regimen, CrCl 0-10, 200 mg every 12 hours. Adequate hydration is maintained. Refer to current product labeling.', 'Store at 20-25 C (68-77 F); excursions permitted to 15-30 C. Protect from moisture.', 'Store at 20-25 C (68-77 F); excursions permitted to 15-30 C. Protect from moisture.', NULL, 'aciclovir', 'Acyclovir tablets FDA label (Apotex) via DailyMed; StatPearls: Acyclovir; VIREAD FDA label (drugs affecting renal function); Goodman & Gilman''s 14th ed.', true),
    ('med_rabies_vaccine', 'Rabies Vaccine (PVRV / PCECV)', 'Rabies vaccine, inactivated: purified Vero cell (PVRV) or purified chick embryo cell (PCECV)', 'Verorab', 'Vaccine (inactivated rabies)', 'Prescription', 'Cell-culture rabies vaccines contain inactivated rabies virus grown in Vero cells (PVRV) or chick embryo cells (PCECV). They induce virus-neutralizing antibodies, which take time to develop, so post-exposure prophylaxis combines immediate wound washing, a vaccine course and, for category III exposures, rabies immunoglobulin to cover the gap. Because clinical rabies is almost always fatal, post-exposure prophylaxis has no contraindication.', 'Post-exposure prophylaxis (category II: vaccine; category III: vaccine plus rabies immunoglobulin), previously unvaccinated persons. WHO regimens: intradermal 1-week, 2-site regimen, 0.1 mL at 2 sites on days 0, 3 and 7; intramuscular 2-week (Essen) regimen, 1 dose on days 0, 3, 7 and between day 14 and 28; intramuscular 3-week (Zagreb) regimen, 2 doses on day 0 and 1 dose on days 7 and 21. US labeling (PCECV, 1 mL IM in the deltoid, never gluteal): days 0, 3, 7, 14 and 28 with HRIG; CDC uses 4 doses (days 0, 3, 7, 14) in immunocompetent persons and a fifth dose on day 28 in immunocompromised persons. Previously vaccinated persons: WHO 1-site ID on days 0 and 3 or 4-site ID on day 0; US label 1 mL IM on days 0 and 3; no immunoglobulin. Once started, PEP is not interrupted for local or mild systemic reactions. In the Philippines, PEP is delivered through DOH-certified Animal Bite Treatment Centers and covered by the PhilHealth Animal Bite Package. Refer to current product labeling.', 'Post-exposure prophylaxis (category II: vaccine; category III: vaccine plus rabies immunoglobulin), previously unvaccinated persons. WHO regimens: intradermal 1-week, 2-site regimen, 0.1 mL at 2 sites on days 0, 3 and 7; intramuscular 2-week (Essen) regimen, 1 dose on days 0, 3, 7 and between day 14 and 28; intramuscular 3-week (Zagreb) regimen, 2 doses on day 0 and 1 dose on days 7 and 21. US labeling (PCECV, 1 mL IM in the deltoid, never gluteal): days 0, 3, 7, 14 and 28 with HRIG; CDC uses 4 doses (days 0, 3, 7, 14) in immunocompetent persons and a fifth dose on day 28 in immunocompromised persons. Previously vaccinated persons: WHO 1-site ID on days 0 and 3 or 4-site ID on day 0; US label 1 mL IM on days 0 and 3; no immunoglobulin. Once started, PEP is not interrupted for local or mild systemic reactions. In the Philippines, PEP is delivered through DOH-certified Animal Bite Treatment Centers and covered by the PhilHealth Animal Bite Package. Refer to current product labeling.', 'Store at 2-8 C (36-46 F), protected from light; do not freeze; use immediately after reconstitution.', 'Store at 2-8 C (36-46 F), protected from light; do not freeze; use immediately after reconstitution.', NULL, 'rabies vaccine', 'WHO position paper on rabies vaccines and immunoglobulins (2018) and WHO PEP recommendations page; WHO rabies fact sheet; RABAVERT (PCECV) FDA label via DailyMed; StatPearls: Rabies; PhilHealth Circular No. 015 s. 2012 (Animal Bite Package); Goodman & Gilman''s 14th ed.', true),
    ('med_rabies_immunoglobulin', 'Rabies Immunoglobulin (HRIG / ERIG)', 'Rabies immunoglobulin: human (HRIG) or purified equine (ERIG)', '', 'Passive immunization (immunoglobulin)', 'Prescription', 'Rabies immunoglobulin provides ready-made rabies virus-neutralizing antibodies, prepared from the plasma of immunized human donors (HRIG) or from hyperimmunized horses as purified equine immunoglobulin or F(ab'')2 fragments (ERIG). Infiltrated into and around the wound, it neutralizes virus at the inoculation site before vaccine-induced antibodies appear. It is used with rabies vaccine for category III exposures in persons not previously vaccinated.', 'Single dose at the start of post-exposure prophylaxis, preferably with the first vaccine dose and not beyond day 7 after the first vaccine dose. HRIG: 20 IU/kg body weight (all ages). ERIG: 40 IU/kg body weight. As much of the dose as anatomically feasible is infiltrated into and around the wound(s); WHO advises wound infiltration rather than injecting the remainder at a distant site, while US HRIG labeling gives any remainder intramuscularly at a site distant from vaccine administration. Never given in the same syringe or at the same site as vaccine, and not repeated. WHO considers skin testing before modern ERIG unnecessary. Not given to persons who were previously vaccinated. Refer to current product labeling.', 'Single dose at the start of post-exposure prophylaxis, preferably with the first vaccine dose and not beyond day 7 after the first vaccine dose. HRIG: 20 IU/kg body weight (all ages). ERIG: 40 IU/kg body weight. As much of the dose as anatomically feasible is infiltrated into and around the wound(s); WHO advises wound infiltration rather than injecting the remainder at a distant site, while US HRIG labeling gives any remainder intramuscularly at a site distant from vaccine administration. Never given in the same syringe or at the same site as vaccine, and not repeated. WHO considers skin testing before modern ERIG unnecessary. Not given to persons who were previously vaccinated. Refer to current product labeling.', 'Store at 2-8 C (36-46 F); do not freeze. HyperRAB may be kept at room temperature up to 25 C for up to 6 months within its expiry.', 'Store at 2-8 C (36-46 F); do not freeze. HyperRAB may be kept at room temperature up to 25 C for up to 6 months within its expiry.', NULL, 'rabies immunoglobulin', 'WHO position paper on rabies vaccines and immunoglobulins (2018); HYPERRAB (rabies immune globulin, human) FDA label via DailyMed; RABAVERT FDA label; StatPearls: Rabies; Goodman & Gilman''s 14th ed.', true),
    ('med_cetirizine', 'Cetirizine', 'Cetirizine hydrochloride', 'Virlix', 'Antihistamine (second-generation H1 antagonist)', 'OTC', 'Cetirizine, derived from hydroxyzine, is a fast-acting, highly selective peripheral histamine H1-receptor antagonist. It crosses the blood-brain barrier only minimally, so it causes less sedation than first-generation antihistamines, and it also reduces neutrophil and eosinophil infiltration. It is used for seasonal and perennial allergic rhinitis and chronic urticaria.', 'Adults and children 12 years and older: 5-10 mg orally once daily depending on symptom severity; OTC labeling directs one 10 mg tablet once daily, not more than one in 24 hours, for ages 6-64, with adults 65 years and older asking a doctor. Renal impairment (CrCl 11-31 mL/min) or hepatic impairment: 5 mg once daily. May be taken with or without food. Refer to current product labeling.', 'Adults and children 12 years and older: 5-10 mg orally once daily depending on symptom severity; OTC labeling directs one 10 mg tablet once daily, not more than one in 24 hours, for ages 6-64, with adults 65 years and older asking a doctor. Renal impairment (CrCl 11-31 mL/min) or hepatic impairment: 5 mg once daily. May be taken with or without food. Refer to current product labeling.', 'Store at 20-25 C (68-77 F).', 'Store at 20-25 C (68-77 F).', NULL, 'cetirizine', 'ZYRTEC ALLERGY (cetirizine HCl) OTC Drug Facts label via DailyMed; StatPearls: Cetirizine; Goodman & Gilman''s 14th ed.', true),
    ('med_zinc_sulfate', 'Zinc Sulfate', 'Zinc sulfate (monohydrate)', 'E-Zinc', 'Mineral supplement (zinc)', 'OTC', 'Zinc is an essential trace element that serves as a cofactor for many enzymes and transcription factors involved in immunity, epithelial repair and growth. In acute diarrhea it inhibits several intracellular pathways of intestinal ion secretion (cAMP, calcium and nitric oxide) and supports mucosal recovery; WHO and UNICEF have recommended zinc with oral rehydration salts for all childhood diarrhea episodes since 2004. It is also used to correct zinc deficiency and, as zinc salts, in Wilson disease.', 'Acute or persistent diarrhea in children up to 5 years (WHO-prequalified zinc sulfate product): under 6 months, 10 mg elemental zinc once daily; 6 months to 5 years, 20 mg elemental zinc once daily; for 10-14 days together with reduced-osmolarity ORS, continued even after diarrhea stops. Adults: recommended dietary allowance 11 mg/day (men) and 8 mg/day (women), 11 mg/day in pregnancy and 12 mg/day in lactation; tolerable upper intake level 40 mg/day of elemental zinc. Doses are expressed as elemental zinc, which differs from the zinc sulfate salt weight. Refer to current product labeling.', 'Acute or persistent diarrhea in children up to 5 years (WHO-prequalified zinc sulfate product): under 6 months, 10 mg elemental zinc once daily; 6 months to 5 years, 20 mg elemental zinc once daily; for 10-14 days together with reduced-osmolarity ORS, continued even after diarrhea stops. Adults: recommended dietary allowance 11 mg/day (men) and 8 mg/day (women), 11 mg/day in pregnancy and 12 mg/day in lactation; tolerable upper intake level 40 mg/day of elemental zinc. Doses are expressed as elemental zinc, which differs from the zinc sulfate salt weight. Refer to current product labeling.', 'Store below 30 C, protected from light and moisture (WHO-prequalified dispersible tablets); follow the label of the specific product.', 'Store below 30 C, protected from light and moisture (WHO-prequalified dispersible tablets); follow the label of the specific product.', NULL, 'zinc sulfate', 'WHO-prequalified zinc sulfate 20 mg dispersible tablets SmPC (WHOPAR DI005); NIH Office of Dietary Supplements Zinc fact sheet for health professionals; StatPearls: Zinc; WHO e-Library of Evidence for Nutrition Actions (zinc for diarrhoea); Goodman & Gilman''s 14th ed.', true);
