    ('med_rabies_vaccine', 'indication', 'Post-exposure prophylaxis after category II exposure (nibbling of uncovered skin, minor scratches or abrasions without bleeding)', 0),
    ('med_rabies_vaccine', 'indication', 'Post-exposure prophylaxis after category III exposure (transdermal bites or scratches, mucous membrane or broken-skin contamination with saliva), together with rabies immunoglobulin', 1),
    ('med_rabies_vaccine', 'indication', 'Post-exposure booster series in previously vaccinated persons (no immunoglobulin required)', 2),
    ('med_rabies_vaccine', 'indication', 'Pre-exposure prophylaxis (primary series and boosters) for persons at increased risk of exposure', 3),
    ('med_rabies_vaccine', 'adverse', 'Injection-site erythema, induration and pain', 0),
    ('med_rabies_vaccine', 'adverse', 'Flu-like symptoms: fatigue, fever, headache, myalgia, malaise', 1),
    ('med_rabies_vaccine', 'adverse', 'Arthralgia, dizziness, lymphadenopathy, nausea and rash', 2),
    ('med_rabies_vaccine', 'adverse', 'Hypersensitivity reactions including anaphylaxis (rare)', 3),
    ('med_rabies_vaccine', 'adverse', 'Neurologic events temporally associated with vaccination (rare): Guillain-Barre syndrome, encephalitis, transient paralysis, myelitis, retrobulbar neuritis', 4),
    ('med_rabies_vaccine', 'contraindication', 'Post-exposure prophylaxis: no contraindication, including pregnancy, because rabies is nearly always fatal', 0),
    ('med_rabies_vaccine', 'contraindication', 'Pre-exposure vaccination: history of anaphylaxis to the vaccine or any component', 1),
    ('med_rabies_vaccine', 'contraindication', 'PCECV contains egg (chicken) protein, gelatin and trace antibiotics such as neomycin; in severe allergy an alternative vaccine is used if available, with epinephrine at hand', 2),
    ('med_rabies_vaccine', 'contraindication', 'Not injected into the gluteal region (lower antibody titers) or intravascularly', 3),
    ('med_rabies_vaccine', 'interaction', 'Corticosteroids, other immunosuppressive agents, antimalarials and radiation therapy: may impair the antibody response; serum neutralizing antibody is checked (e.g., on day 14) when PEP is given during such therapy.', 0),
    ('med_rabies_vaccine', 'interaction', 'Chloroquine or hydroxychloroquine: pre-exposure vaccination is completed before starting these drugs whenever possible.', 1),
    ('med_rabies_vaccine', 'interaction', 'Rabies immunoglobulin: never mixed in the same syringe or injected at the same anatomical site as the vaccine.', 2),
    ('med_rabies_vaccine', 'interaction', 'Rabies immunoglobulin above the recommended dose, or repeated doses: can suppress active antibody production to the vaccine.', 3),
    ('med_rabies_immunoglobulin', 'brand_intl', 'HyperRAB', 0),
    ('med_rabies_immunoglobulin', 'indication', 'Category III rabies exposures (single or multiple transdermal bites or scratches, contamination of mucous membranes or broken skin with saliva) in previously unvaccinated persons, together with rabies vaccine', 0),
    ('med_rabies_immunoglobulin', 'indication', 'Wound infiltration at the start of post-exposure prophylaxis, up to day 7 after the first vaccine dose', 1),
    ('med_rabies_immunoglobulin', 'indication', 'Post-exposure prophylaxis in immunocompromised persons, who receive both vaccine and immunoglobulin even after prior vaccination', 2),
    ('med_rabies_immunoglobulin', 'indication', 'Post-exposure prophylaxis for all ages, including children and pregnant women', 3),
    ('med_rabies_immunoglobulin', 'adverse', 'Injection-site pain and nodules', 0),
    ('med_rabies_immunoglobulin', 'adverse', 'Headache, abdominal pain, diarrhea, flatulence, nasal congestion, oropharyngeal pain (HRIG, > 5%)', 1),
    ('med_rabies_immunoglobulin', 'adverse', 'Hypersensitivity reactions including anaphylaxis; greater risk in IgA deficiency (HRIG)', 2),
    ('med_rabies_immunoglobulin', 'adverse', 'ERIG: adverse reactions in about 0.8-6% of recipients, mostly minor but more frequent than with HRIG', 3),
    ('med_rabies_immunoglobulin', 'adverse', 'Theoretical risk of transmission of infectious agents from human plasma (HRIG)', 4),
    ('med_rabies_immunoglobulin', 'contraindication', 'No contraindications are listed in the HyperRAB label', 0),
    ('med_rabies_immunoglobulin', 'contraindication', 'Not indicated for persons previously vaccinated with a complete pre- or post-exposure series', 1),
    ('med_rabies_immunoglobulin', 'contraindication', 'Not administered later than day 7 after the first vaccine dose, or as repeated doses', 2),
    ('med_rabies_immunoglobulin', 'contraindication', 'Hypersensitivity to human immunoglobulins or IgA deficiency (precaution; epinephrine must be available)', 3),
    ('med_rabies_immunoglobulin', 'interaction', 'Rabies vaccine: never administered in the same syringe or at the same anatomical site as the vaccine.', 0),
    ('med_rabies_immunoglobulin', 'interaction', 'Rabies vaccine (repeat or excess immunoglobulin): repeating the dose after vaccine initiation or exceeding the recommended dose may suppress the active antibody response.', 1),
    ('med_rabies_immunoglobulin', 'interaction', 'Live attenuated virus vaccines (e.g., measles, mumps, rubella): antibodies may interfere with the response; these vaccines are deferred for about 4 months after HRIG.', 2),
    ('med_rabies_immunoglobulin', 'interaction', 'Corticosteroids and other immunosuppressants: may blunt the vaccine response that the immunoglobulin is bridging; serology is used to confirm response in immunosuppressed persons.', 3),
